{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "pod_failure",
      "evidence": [
        {"kind": "metric", "sql": "SELECT CAST(time AS VARCHAR) t, metric, value FROM abnormal_metrics WHERE attr_k8s_pod_name='search-7d9cf4559d-ktsrp' AND metric='k8s.container.restarts' ORDER BY time", "claim": "Search pod restart counter climbs from 4 to 8 during the incident, versus a flat 3 in the normal period."},
        {"kind": "metric", "sql": "SELECT p, pod, count(*) n FROM (SELECT 'normal' p, attr_k8s_pod_name pod, metric FROM normal_metrics UNION ALL SELECT 'abnormal', attr_k8s_pod_name, metric FROM abnormal_metrics) WHERE pod LIKE 'search-%' AND metric='k8s.pod.uptime' GROUP BY ALL", "claim": "Search pod emits no k8s.pod.uptime samples in the abnormal period, consistent with repeated restarts."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='search.Search/Nearby' GROUP BY ALL", "claim": "All 565 frontend calls to search.Search/Nearby end in Error after about 0.016 ms; search returns no spans."},
        {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND attr_status_code='Error' GROUP BY ALL", "claim": "Frontend /hotels server spans return HTTP 500 for all 565 requests during the incident."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND (span_name='search.Search/Nearby' OR span_name='HTTP /hotels') GROUP BY ALL", "claim": "Frontend search client calls and the /hotels HTTP spans both fail, so user hotel searches return errors."}
      ]
    }
  ]
}
